import typography from '@dynatrace/strato-design-tokens/typography';

import { SIZE_24, SIZE_16, SIZE_8 } from '../types/default.js';
import { ChartSizes } from '../types/meter-bars.js';

const SMALL_ICON_SIZE = 16;
const DEFAULT_ICON_SIZE = 20;
const LARGE_ICON_SIZE = 24;
const SMALL_CHART_SIZE = 8;
const DEFAULT_CHART_SIZE = 16;
const LARGE_CHART_SIZE = 24;

export const getChartElementsSizes = (chartSize: string): ChartSizes => {
  switch (chartSize) {
    case SIZE_8: {
      return {
        icon: SMALL_ICON_SIZE,
        label: typography.Heading.Level5,
        value: typography.Text.Small.Default,
        chartHeight: SMALL_CHART_SIZE,
      };
    }

    case SIZE_16: {
      return {
        icon: DEFAULT_ICON_SIZE,
        label: typography.Heading.Level4,
        value: typography.Text.Base.Default,
        chartHeight: DEFAULT_CHART_SIZE,
      };
    }

    case SIZE_24: {
      return {
        icon: LARGE_ICON_SIZE,
        label: typography.Heading.Level3,
        value: typography.Subtitle.Heading.Level3,
        chartHeight: LARGE_CHART_SIZE,
      };
    }

    default: {
      return {
        icon: DEFAULT_ICON_SIZE,
        label: typography.Heading.Level4,
        value: typography.Text.Base.Default,
        chartHeight: DEFAULT_CHART_SIZE,
      };
    }
  }
};
